import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.CPZ999nZ.js";const p=JSON.parse('{"title":"Datadog Agent version","description":"","frontmatter":{},"headers":[],"relativePath":"development/agent-version.md","filePath":"development/agent-version.md","lastUpdated":1795784283000}'),n={name:"development/agent-version.md"};function o(d,e,r,h,l,c){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="datadog-agent-version" tabindex="-1">Datadog Agent version <a class="header-anchor" href="#datadog-agent-version" aria-label="Permalink to &quot;Datadog Agent version&quot;">​</a></h1><p>Saluki builds with and tests against one Datadog Agent build, recorded in <code>.datadog-agent-version.json</code> at the repository root. This page covers that file, the CI jobs and local commands that use it, how it&#39;s updated, and the version gates that switch ADP behavior by Agent version.</p><p>The file is the only committed Agent version for builds, tests and benchmarks. CI jobs, Make targets, and Dockerfile build arguments all derive their Agent inputs from it. Only the scheduled <code>AGENT_NIGHTLY</code> pipeline stays outside it, and keeps testing against floating Agent images. The SMP benchmark (<code>.gitlab/benchmark.yml</code>) runs its baseline and comparison with the Agent in the file at the pipeline&#39;s commit, so the comparison measures only the ADP change.</p><h2 id="versions" tabindex="-1">Versions <a class="header-anchor" href="#versions" aria-label="Permalink to &quot;Versions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>Integration version</td><td>The Agent that CI builds with and tests against: Linux and Windows images, macOS packages, and debug packages from one Agent commit. The file&#39;s <code>integration</code> section.</td></tr><tr><td>Declared version</td><td>The <code>DD_AGENT_VERSION</code> compiled into the Linux ADP build, which drives version gates. On <code>main</code> it&#39;s the Integration version. On a release branch it&#39;s the target minor&#39;s patch zero, such as <code>7.87.0</code>, whatever the Integration version is.</td></tr><tr><td>Target minor</td><td>The Agent minor that an ADP release line supports, in the file&#39;s <code>target</code> field. Only release branches have it, and it must match the line&#39;s entry in <code>.datadog-agent-release-lines.jsonl</code>. See <a href="./../agent-data-plane/releasing#release-lines-and-their-target">Releasing ADP</a>.</td></tr></tbody></table><p>Only the jobs that compile the Linux ADP image, and the release tarballs built from it, set <code>DD_AGENT_VERSION</code>. Unit test and lint jobs don&#39;t, and Make doesn&#39;t export it. Native macOS and Windows ADP builds don&#39;t set it either, so their version gates select the newest behavior.</p><h2 id="what-target-changes" tabindex="-1">What <code>target</code> changes <a class="header-anchor" href="#what-target-changes" aria-label="Permalink to &quot;What `target` changes&quot;">​</a></h2><p><code>main</code> has no <code>target</code>. A release branch adds one when it&#39;s cut. The tooling in <code>ci/tooling</code> reads the field and behaves differently with it:</p><table tabindex="0"><thead><tr><th></th><th><code>main</code>, no <code>target</code></th><th>Release branch, <code>&quot;target&quot;: &quot;7.87&quot;</code></th></tr></thead><tbody><tr><td><code>DD_AGENT_VERSION</code> for the Linux ADP build</td><td>The Integration version, such as <code>7.87.0-devel+git.394.462b537.pipeline.151347634</code></td><td><code>7.87.0</code></td></tr><tr><td>Version gates</td><td>The newest behavior: a development version passes every gate</td><td>The behavior of Agent 7.87</td></tr><tr><td>Allowed Integration version</td><td>A nightly</td><td>A nightly, RC, or stable release, but only from 7.87</td></tr><tr><td>Updated by</td><td><strong>Update Agent Nightly</strong>, to newer nightlies</td><td><strong>Update Agent Release Version</strong>, to newer 7.87 RCs, then stable releases</td></tr><tr><td>Pull request check</td><td>Rejects <code>target</code> and anything but a nightly</td><td>Requires <code>target</code> to match the line&#39;s release-lines entry, and rejects any change to it or removal of the file</td></tr><tr><td>Release tag check</td><td>None</td><td>The tag must be on the branch and declare the line&#39;s target</td></tr></tbody></table><p>In code, <code>declared_version</code>, <code>check_change</code>, and <code>check_release_tag</code> in <code>ci/tooling/agent_version.py</code> make these choices, and <code>discover_agent_version.py release</code> refuses to run without a target.</p><h2 id="what-the-file-contains" tabindex="-1">What the file contains <a class="header-anchor" href="#what-the-file-contains" aria-label="Permalink to &quot;What the file contains&quot;">​</a></h2><p>Every version file is complete. It has:</p><ul><li>the Linux multi-platform image, by index digest, with its <code>amd64</code> and <code>arm64</code> child digests</li><li>the Windows <code>ltsc2022</code> server core image with JMX, by child digest</li><li>the macOS DMGs for <code>arm64</code> and <code>x86_64</code>, with SHA-256 checksums</li><li>the Agent debug packages for <code>amd64</code> and <code>arm64</code>, with SHA-256 checksums</li></ul><p>All artifacts come from one Agent commit, <code>git_revision</code>. A nightly also records the upstream pipeline ID, which appears in the nightly version string. Package URLs must be the long-lived locations derived from the version; the expiring macOS <code>ci/</code> packages are rejected. <code>built_at</code> is the creation time of the Linux <code>amd64</code> image, and the Integration version&#39;s age is measured from it.</p><p><code>ci/tooling/agent_version.py</code> holds the exact schema and rules. To validate the file, run:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-agent-version</span></span></code></pre></div><p>Consumers pull images by digest and verify each package&#39;s checksum before they use it, including cached copies. A mismatch or a failed pull fails the job.</p><h2 id="reading-the-file" tabindex="-1">Reading the file <a class="header-anchor" href="#reading-the-file" aria-label="Permalink to &quot;Reading the file&quot;">​</a></h2><p>CI reads the checked-out file in job scripts: <code>jq</code> on Linux and <code>ConvertFrom-Json</code> on Windows. Make recipes read it with <code>ci/tooling/agent_version.py</code> only when they need it, so targets such as <code>make fmt</code> work without it. The reader validates the file before it prints anything:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci/tooling/agent_version.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> integration.linux.image</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # one field</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci/tooling/agent_version.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> declared-version</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # the Declared version</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci/tooling/agent_version.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> age</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                           # age, measured from built_at</span></span></code></pre></div><h2 id="using-the-agent-locally" tabindex="-1">Using the Agent locally <a class="header-anchor" href="#using-the-agent-locally" aria-label="Permalink to &quot;Using the Agent locally&quot;">​</a></h2><p>Dockerfiles can&#39;t read the file before <code>FROM</code>, so they take the resolved values as build arguments and fail when one is missing. Use these Make targets, which pass the values for you:</p><table tabindex="0"><thead><tr><th>Command</th><th>Uses</th></tr></thead><tbody><tr><td><code>make build-datadog-agent-image</code>, <code>make build-datadog-agent-image-release</code></td><td>The Linux image, as the base of the bundled Agent and ADP image</td></tr><tr><td><code>make provision-macos-test-env</code></td><td>The macOS DMG for the host architecture, installed into a sandbox under <code>/tmp</code></td></tr><tr><td><code>make antithesis-build</code>, <code>make antithesis-build-differential</code></td><td>The bundled image, and the <code>amd64</code> debug package for the Antithesis scenarios</td></tr></tbody></table><p>The macOS install, <code>ci/tooling/install_macos_agent.py</code>, writes a marker with the version, URL, and checksum after a successful install. Later runs reuse the installation only when the marker matches the file and the Agent executable exists. The macOS integration test jobs in CI use the same Make target.</p><p>To build an Antithesis scenario with Compose directly, export the debug package first:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AGENT_DEBUG_DEB_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci/tooling/agent_version.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> integration.antithesis_debug_debs.amd64.url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AGENT_DEBUG_DEB_SHA256</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci/tooling/agent_version.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> integration.antithesis_debug_debs.amd64.sha256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/antithesis/scenarios/general/docker-compose.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><h2 id="updating-the-file" tabindex="-1">Updating the file <a class="header-anchor" href="#updating-the-file" aria-label="Permalink to &quot;Updating the file&quot;">​</a></h2><p>Nobody edits the artifact fields by hand. <code>ci/tooling/update-agent-version/discover_agent_version.py</code> finds a complete artifact set, downloads and hashes every package, and writes a new file. Automation and people use the same tool, and a failed or partial discovery never writes a file.</p><h3 id="where-discovery-finds-the-artifacts" tabindex="-1">Where discovery finds the artifacts <a class="header-anchor" href="#where-discovery-finds-the-artifacts" aria-label="Permalink to &quot;Where discovery finds the artifacts&quot;">​</a></h3><p>Discovery starts from an Agent version and derives every other location from it:</p><table tabindex="0"><thead><tr><th>Artifact</th><th>Nightly</th><th>RC</th><th>Stable release</th></tr></thead><tbody><tr><td>Linux image</td><td><code>datadog/agent-dev:nightly-full-main-&lt;sha8&gt;-jmx</code></td><td><code>registry.datadoghq.com/agent:&lt;version&gt;-full</code></td><td>Same as RC</td></tr><tr><td>Windows image</td><td>The <code>ltsc2022</code> child of the floating <code>datadog/agent-dev:nightly-py3-jmx-win-servercore</code></td><td>The <code>ltsc2022</code> child of <code>registry.datadoghq.com/agent:&lt;version&gt;-servercore-ltsc2022-jmx</code></td><td>Same as RC</td></tr><tr><td>macOS DMGs</td><td><code>s3.amazonaws.com/dd-agent-macostesting/nightly/</code></td><td><code>s3.amazonaws.com/dd-agent-macostesting/beta/</code></td><td><code>s3.amazonaws.com/dd-agent/</code></td></tr><tr><td>Debug packages</td><td><code>apt.datad0g.com</code></td><td><code>apt.datad0g.com</code></td><td><code>apt.datadoghq.com</code></td></tr></tbody></table><p>For a nightly, the version comes from the Windows image&#39;s labels. For an RC or stable release, it comes from the Agent&#39;s Git tags. Discovery resolves each image tag to a digest and requires the image&#39;s version and revision labels to match. It then downloads each package and records its SHA-256. If an artifact isn&#39;t published yet, it skips that version, and a later run tries again.</p><h3 id="on-main" tabindex="-1">On <code>main</code> <a class="header-anchor" href="#on-main" aria-label="Permalink to &quot;On `main`&quot;">​</a></h3><p>The <strong>Update Agent Nightly</strong> workflow (<code>.github/workflows/update-agent-nightly.yml</code>) looks for a newer Agent <code>main</code> nightly. It runs daily at 12:30 UTC and on manual dispatch. It resolves the floating Windows nightly image once, then requires the Linux nightly built from the same commit and pipeline, and all four packages. The candidate must have a higher pipeline ID than the current nightly and an Agent commit equal to or ahead of it.</p><p>The workflow keeps one bot branch, <code>ci/update-agent-nightly</code>, and at most one open pull request. It refreshes that pull request only while the pull request holds nothing but the automated update. Each refresh is based on the current <code>main</code>, and it moves the bot branch only by fast-forward, so a push that arrives during a run makes the run fail rather than overwriting it. If the new Agent needs an ADP change, push it to the bot branch: the pull request then keeps its candidate, and the workflow proposes nothing newer until it merges or closes. After a pull request closes without merging, the next run restarts the bot branch from <code>main</code> and opens a new pull request. If <code>main</code>&#39;s version file changes while a run is in progress, that run proposes nothing, and the next run discovers again.</p><p>The Windows nightly is published under a floating tag, so a missed run can&#39;t find an older Windows build later. To bootstrap the file or recover a missed nightly, take the <code>ltsc2022</code> child digest from the upstream Windows build job&#39;s push log and pass it as the workflow&#39;s <code>windows_digest</code> input, or run the tool yourself:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci/tooling/update-agent-version/discover_agent_version.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nightly</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/agent-version</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --windows-digest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sha256:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">diges</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/agent-version/datadog-agent-version.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .datadog-agent-version.json</span></span></code></pre></div><p>Every run reports the current nightly&#39;s age, even when it finds nothing newer. Nothing alerts on an old nightly.</p><h3 id="on-release-branches" tabindex="-1">On release branches <a class="header-anchor" href="#on-release-branches" aria-label="Permalink to &quot;On release branches&quot;">​</a></h3><p>The <strong>Update Agent Release Version</strong> workflow (<code>.github/workflows/update-agent-version.yml</code>) runs weekly from <code>main</code> over the release lines listed in its <code>MAINTAINED_LINES</code>. While that list is empty, it changes nothing. For each line that has adopted the file, it proposes the newest complete RC or stable Agent release within the line&#39;s target minor, in a pull request against that branch. It changes only <code>integration</code>, never <code>target</code>. <a href="./../agent-data-plane/releasing#agent-updates-within-a-release-line">Releasing ADP</a> describes the order it follows, and <a href="./../agent-data-plane/releasing#cutting-a-new-release-line">Cutting a new release line</a> covers the first version of a new line.</p><h3 id="when-an-update-workflow-fails" tabindex="-1">When an update workflow fails <a class="header-anchor" href="#when-an-update-workflow-fails" aria-label="Permalink to &quot;When an update workflow fails&quot;">​</a></h3><p>Discovery separates two outcomes:</p><ul><li>A <strong>skip</strong> is normal. The newest build is incomplete, isn&#39;t newer, or came from an Agent release branch. The run passes, says why in its summary, and changes nothing.</li><li>An <strong>error</strong> means something unexpected: a registry that keeps failing past the retry budget, a malformed response, or an artifact whose name, labels, or platforms don&#39;t match what the tooling knows. The run fails, and the error at the top of the run names the artifact, what it found, and what it expected.</li></ul><p>Errors usually mean the Agent changed how it names or labels its artifacts. Fix the matching constant or pattern: <code>NIGHTLY_VERSION_RE</code> and the URL helpers in <code>ci/tooling/agent_version.py</code>, or the tag names at the top of <code>discover_agent_version.py</code>. The tests next to each file cover the formats they expect. A registry error is often transient: rerun the workflow before changing code.</p><p>The workflows can&#39;t post to Slack themselves. To get a message for each scheduled run, subscribe a channel through Slack&#39;s GitHub integration:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/github subscribe DataDog/saluki workflows:{name:&quot;Update Agent Nightly&quot; event:&quot;schedule&quot;}</span></span>\n<span class="line"><span>/github subscribe DataDog/saluki workflows:{name:&quot;Update Agent Release Version&quot; event:&quot;schedule&quot;}</span></span></code></pre></div><h2 id="version-gates" tabindex="-1">Version gates <a class="header-anchor" href="#version-gates" aria-label="Permalink to &quot;Version gates&quot;">​</a></h2><p>A version gate switches between old and new Agent behavior, based on the Declared version that ADP was built with. <code>datadog_agent_commons::agent_version::meets(major, minor, patch)</code> is true when the Declared version is at least that version, and also for development versions and an unset version. On <code>main</code> the Declared version is a nightly, so every gate selects the newest behavior. On a release branch it&#39;s the line&#39;s target minor, such as <code>7.87.0</code>, even when CI tests a later RC or patch.</p><p>For example, <code>LEGACY_TAG_LINKS_AND_EVENTS</code> in <code>lib/saluki-components/src/common/otlp/traces/transform.rs</code> is <code>!meets(7, 87, 0)</code>. A release line that targets 7.86 writes OTLP span links and events as legacy tags. <code>main</code> and lines that target 7.87 or later write them as native span links and events.</p><ul><li>Gate on Agent minor versions, such as <code>meets(7, 87, 0)</code>. Don&#39;t add patch-level gates.</li><li>When an Agent change affects what correctness tests compare, put the matching ADP change in the pull request that updates the nightly, so the code and the test Agent advance together.</li><li>Delete a gate only when every maintained release line declares at least its threshold. Reaching that version on <code>main</code> isn&#39;t enough, and a maintained line that hasn&#39;t adopted the file still counts.</li></ul><h2 id="checks" tabindex="-1">Checks <a class="header-anchor" href="#checks" aria-label="Permalink to &quot;Checks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>Where</th><th>What it enforces</th></tr></thead><tbody><tr><td><strong>Agent version</strong> workflow</td><td>Every pull request</td><td>The file and <code>.datadog-agent-release-lines.jsonl</code> are valid. <code>main</code> takes a nightly without <code>target</code> and maps its ADP line. A release branch that has the file keeps it and keeps its <code>target</code>, which must match the line&#39;s release-lines entry.</td></tr><tr><td><code>check-agent-version</code> GitLab job</td><td>Every pipeline</td><td>The committed file is valid, and the tests for the tooling pass.</td></tr><tr><td><strong>Backport</strong> workflow</td><td>Backports</td><td>A backport doesn&#39;t change <code>.datadog-agent-version.json</code>.</td></tr><tr><td><strong>Bump ADP Version</strong> workflow</td><td><code>X.Y.0</code> tags</td><td>The tag is on <code>releases/X.Y.x</code> and declares the line&#39;s target.</td></tr><tr><td><code>check-release-agent-version</code> GitLab job</td><td>Release tags</td><td>Before publishing: the tag is on its release branch, the ADP version matches the tag, and the file declares the line&#39;s target.</td></tr></tbody></table><p>The checks read the destination branch separately from the proposed change, so deleting the file or <code>target</code> doesn&#39;t exempt a release line that has adopted it.</p><h2 id="the-agent-nightly-pipeline" tabindex="-1">The <code>AGENT_NIGHTLY</code> pipeline <a class="header-anchor" href="#the-agent-nightly-pipeline" aria-label="Permalink to &quot;The `AGENT_NIGHTLY` pipeline&quot;">​</a></h2><p>The scheduled pipeline with <code>AGENT_NIGHTLY</code> set keeps its floating images as an early warning of Agent changes:</p><ul><li>Linux uses <code>${NIGHTLY_AGENT_IMAGE:-datadog/agent-dev:master-py3-full}</code>.</li><li>Windows uses <code>${NIGHTLY_WINDOWS_AGENT_IMAGE:-datadog/agent-dev:main-py3-jmx-win-servercore-ltsc2022}</code>.</li><li>The Linux ADP build compiles with <code>DD_AGENT_VERSION=nightly</code>.</li><li>macOS uses <code>.datadog-agent-version.json</code>.</li></ul><p>It posts its result to Slack, so don&#39;t set <code>AGENT_NIGHTLY</code> on a test branch.</p>',57)])])}const u=t(n,[["render",o]]);export{p as __pageData,u as default};
